// ESP32 UART RECEIVER (test)
// Wiring: Sender GPIO17 (TX2) -> Receiver GPIO16 (RX2)
//         Sender GPIO16 (RX2) <- Receiver GPIO17 (TX2)
//         GND <-> GND  (required!)

#define LED_PIN   2
#define RX2_PIN   16
#define TX2_PIN   17
#define LINK_BAUD 115200   // must match the sender

unsigned long lastRx = 0;

void setup() {
  Serial.begin(115200);                                  // USB serial monitor
  Serial2.begin(LINK_BAUD, SERIAL_8N1, RX2_PIN, TX2_PIN); // link from sender
  pinMode(LED_PIN, OUTPUT);
  delay(500);
  Serial.println("RECEIVER STARTED");
  lastRx = millis();
}

void loop() {
  if (Serial2.available()) {
    String msg = Serial2.readStringUntil('\n');
    msg.trim();

    if (msg.startsWith("MSG:")) {
      Serial.print("Received: ");
      Serial.println(msg);
      digitalWrite(LED_PIN, !digitalRead(LED_PIN));  // toggle LED on each good message
    } else if (msg.length() > 0) {
      // Garbage or unexpected data: print as hex to help debugging
      Serial.print("Unexpected data (hex): ");
      for (size_t i = 0; i < msg.length(); i++) {
        Serial.printf("%02X ", (uint8_t)msg[i]);
      }
      Serial.println();
    }
    lastRx = millis();
  }

  // Warn if nothing arrives for 3 seconds
  if (millis() - lastRx > 3000) {
    Serial.println("No data from sender (check wiring, GND, baud rate)");
    lastRx = millis();
  }
}

// ESP32 UART SENDER (test)
// Wiring: Sender GPIO17 (TX2) -> Receiver GPIO16 (RX2)
//         Sender GPIO16 (RX2) <- Receiver GPIO17 (TX2)
//         GND <-> GND  (required!)

#define LED_PIN   2
#define RX2_PIN   16
#define TX2_PIN   17
#define LINK_BAUD 115200   // must match the receiver

unsigned long counter = 0;

void setup() {
  Serial.begin(115200);                                  // USB serial monitor
  Serial2.begin(LINK_BAUD, SERIAL_8N1, RX2_PIN, TX2_PIN); // link to receiver
  pinMode(LED_PIN, OUTPUT);
  delay(500);
  Serial.println("SENDER STARTED");
}

void loop() {
  digitalWrite(LED_PIN, HIGH);

  // Plain text, newline-terminated, so the receiver can read a full line
  Serial2.print("MSG:");
  Serial2.println(counter);

  Serial.print("Sent: MSG:");
  Serial.println(counter);

  counter++;
  delay(500);

  digitalWrite(LED_PIN, LOW);
  delay(500);
}
